package reviewconsoleapi

const consoleHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenWatchlist Review Console</title><link rel="stylesheet" href="/assets/review-console.css"></head><body><header><strong>OpenWatchlist Review Console</strong><span id="identity">Not authenticated</span><input id="token" type="password" placeholder="Paste short-lived token"><button id="saveToken">Use token</button></header><nav><button data-view="cases">Cases</button><button data-view="alerts">Alerts</button><button data-view="audit">Security audit</button></nav><main><section id="message"></section><section id="content"></section></main><dialog id="detail"><button id="closeDetail">Close</button><div id="detailBody"></div></dialog><script src="/assets/review-console.js"></script></body></html>`
const consoleCSS = `body{font-family:system-ui,sans-serif;margin:0;background:#f4f4f4;color:#171717}header{display:flex;gap:.6rem;align-items:center;padding:1rem;background:#111;color:#fff}header input{margin-left:auto;min-width:24rem}button,input{padding:.55rem}nav,main{padding:1rem}nav{display:flex;gap:.5rem;background:#ddd}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:.55rem;border-bottom:1px solid #ddd;text-align:left}pre{white-space:pre-wrap;background:#111;color:#eee;padding:1rem;max-height:45vh;overflow:auto}.error{background:#ffe5e5;padding:.7rem}.ok{background:#e7f7e7;padding:.7rem}dialog{width:min(70rem,90vw)}`
const consoleJS = `const $=s=>document.querySelector(s);let token=localStorage.getItem('owToken')||'';$('#token').value=token;const esc=v=>String(v).replaceAll('<','&lt;');async function api(path,opt={}){let r=await fetch(path,{...opt,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json',...(opt.headers||{})}});let j=await r.json().catch(()=>({error:'invalid response'}));if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j}function msg(v,ok=false){$('#message').innerHTML='<div class="'+(ok?'ok':'error')+'">'+esc(v)+'</div>'}async function me(){let j=await api('/v1/me');$('#identity').textContent=j.claims.display_name+' · '+j.claims.tenant_id+' · '+j.claims.roles.join(', ')}async function cases(){let j=await api('/v1/cases?limit=100');let rows=j.cases.map(c=>'<tr data-id="'+esc(c.case_id)+'"><td>'+esc(c.case_id)+'</td><td>'+esc(c.state)+'</td><td>'+esc(c.assigned_to||'')+'</td><td>'+c.revision+'</td></tr>').join('');$('#content').innerHTML='<h2>Cases</h2><table><tr><th>ID</th><th>State</th><th>Assigned</th><th>Revision</th></tr>'+rows+'</table>';document.querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>detail(x.dataset.id))}async function alerts(){let j=await api('/v1/alerts?limit=100');$('#content').innerHTML='<h2>Alerts</h2><pre>'+esc(JSON.stringify(j,null,2))+'</pre>'}async function audit(){let j=await api('/v1/security/audit?limit=100');$('#content').innerHTML='<h2>Security audit</h2><pre>'+esc(JSON.stringify(j,null,2))+'</pre>'}async function detail(id){let c=await api('/v1/cases/'+id);let a=await api('/v1/cases/'+id+'/assistance?limit=20');$('#detailBody').innerHTML='<h2>'+esc(id)+'</h2><pre>'+esc(JSON.stringify({case:c,assistance:a},null,2))+'</pre>';$('#detail').showModal()}$('#saveToken').onclick=()=>{token=$('#token').value.trim();localStorage.setItem('owToken',token);me().then(cases).catch(e=>msg(e.message))};$('#closeDetail').onclick=()=>$('#detail').close();document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>({cases,alerts,audit}[b.dataset.view]()).catch(e=>msg(e.message)));if(token)me().then(cases).catch(e=>msg(e.message));`
